import { spawnSync } from "node:child_process";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";

function toConfidence(raw, fallback = 0.9) {
  const num = Number(raw);
  if (!Number.isFinite(num)) return fallback;
  if (num < 0) return 0;
  if (num > 1) return 1;
  return num;
}

function expandHome(inputPath) {
  if (!inputPath) return "";
  const value = String(inputPath);
  if (value === "~") return os.homedir();
  if (value.startsWith("~/")) return path.join(os.homedir(), value.slice(2));
  return value;
}

function extractFileHintsFromText(text) {
  if (!text) return [];
  const matches = [];
  const pattern = /([^\s，。,;；"'`]+?\.(?:psd|psb))/gi;
  for (const match of String(text).matchAll(pattern)) {
    const raw = String(match[1] || "").trim();
    const token = raw
      .split(/[：:]/)
      .pop()
      ?.replace(/^[“"'`【\[]+|[”"'`】\]]+$/g, "")
      .trim();
    if (!token) continue;
    matches.push(token);
  }
  // Keep stable order while deduplicating.
  return Array.from(new Set(matches));
}

function runTesseractOcr(imagePath) {
  const result = spawnSync("tesseract", [imagePath, "stdout", "-l", "chi_sim+eng", "--psm", "6"], {
    encoding: "utf8",
    timeout: 20_000,
  });
  if (result.status === 0) {
    return (result.stdout || "").trim();
  }
  const fallback = spawnSync("tesseract", [imagePath, "stdout", "-l", "eng", "--psm", "6"], {
    encoding: "utf8",
    timeout: 20_000,
  });
  if (fallback.status === 0) {
    return (fallback.stdout || "").trim();
  }
  return "";
}

function runVisionOcr(imagePath) {
  const script = `
import Foundation
import Vision

if CommandLine.arguments.count < 2 {
  exit(0)
}
let imagePath = CommandLine.arguments[1]
let url = URL(fileURLWithPath: imagePath)
let request = VNRecognizeTextRequest()
request.recognitionLevel = .accurate
request.usesLanguageCorrection = true
request.recognitionLanguages = ["zh-Hans", "en-US"]
let handler = VNImageRequestHandler(url: url, options: [:])
do {
  try handler.perform([request])
  let lines = (request.results as? [VNRecognizedTextObservation] ?? []).compactMap { obs in
    obs.topCandidates(1).first?.string
  }
  print(lines.joined(separator: "\\n"))
} catch {
  exit(0)
}
`;
  const result = spawnSync("swift", ["-", imagePath], {
    encoding: "utf8",
    timeout: 120_000,
    input: script,
  });
  if (result.status === 0) {
    return (result.stdout || "").trim();
  }
  return "";
}

function extractFileHintsFromScreenshot(screenshotPath) {
  const resolvedPath = path.resolve(expandHome(screenshotPath));
  if (!resolvedPath || !fs.existsSync(resolvedPath)) return [];
  const tesseractText = runTesseractOcr(resolvedPath);
  const ocrText = tesseractText || runVisionOcr(resolvedPath);
  return extractFileHintsFromText(ocrText);
}

function extractScreenshotOcrText(screenshotPath) {
  const resolvedPath = path.resolve(expandHome(screenshotPath));
  if (!resolvedPath || !fs.existsSync(resolvedPath)) return "";
  const tesseractText = runTesseractOcr(resolvedPath);
  return tesseractText || runVisionOcr(resolvedPath);
}

function normalizeEdit(item) {
  const op = item?.op === "delete_text" ? "delete_text" : "replace_text";
  const layerName = String(item?.layerName || "").trim();
  const newText =
    op === "delete_text" ? "" : typeof item?.newText === "string" ? item.newText : "";
  return {
    op,
    layerName,
    newText,
    confidence: toConfidence(item?.confidence, op === "delete_text" ? 0.86 : 0.9),
    positionHint: typeof item?.positionHint === "string" ? item.positionHint.trim() : "",
  };
}

function parseEditsFromChinese(text) {
  const edits = [];
  const replacePattern =
    /(?:把)?([^，,。]+?)改成([\s\S]+?)(?=(?:，|,)?(?:把)?[^，,。]+?改成|(?:，|,)?(?:删除|移除|去掉|并保存|并导出|保存成|保存到|放置在|然后|$))/g;
  for (const match of text.matchAll(replacePattern)) {
    const layerName = (match[1] || "").trim();
    const newText = (match[2] || "").trim().replace(/[，,。]\s*$/, "");
    if (!layerName || !newText) continue;
    edits.push(
      normalizeEdit({
        op: "replace_text",
        layerName,
        newText,
      }),
    );
  }

  const deletePattern =
    /(?:删除|移除|去掉)(?:图层)?\s*["“]?([^"”。，,]+)["”]?(?:\s*(?:文字|文案|内容))?/g;
  for (const match of text.matchAll(deletePattern)) {
    const layerName = (match[1] || "").trim();
    if (!layerName) continue;
    edits.push(
      normalizeEdit({
        op: "delete_text",
        layerName,
      }),
    );
  }
  return edits;
}

function parseFileHint(text) {
  const fileMatch = text.match(/(?:找到|找)\s*([^\s，。,]+?\.(?:psd|psb))/i);
  return fileMatch?.[1]?.trim();
}

function parseAbsolutePath(text) {
  if (!text) return "";
  const match = String(text).match(/(\/[^\s，。,]+?\.(?:psd|psb))/i);
  const candidate = match?.[1]?.trim();
  if (!candidate) return "";
  return fs.existsSync(candidate) ? candidate : "";
}

function parseEditsFromOcrText(rawText) {
  const text = String(rawText || "").replaceAll("\r", "\n");
  const edits = [];
  const lines = text
    .split("\n")
    .map((line) => line.trim())
    .filter(Boolean);

  for (const line of lines) {
    const replaceMatch = line.match(/^(.{1,40}?)(?:改成|改为|改到|改)(.{1,40})$/);
    if (replaceMatch) {
      const left = (replaceMatch[1] || "").trim();
      const right = (replaceMatch[2] || "").trim();
      if (left && right && left !== right) {
        edits.push(
          normalizeEdit({
            op: "replace_text",
            layerName: left,
            newText: right,
            confidence: 0.78,
            positionHint: "from_screenshot_ocr",
          }),
        );
      }
      continue;
    }
    const deleteMatch = line.match(/^(?:删除|移除|去掉)(.{1,40})$/);
    if (deleteMatch) {
      const target = (deleteMatch[1] || "").trim();
      if (target) {
        edits.push(
          normalizeEdit({
            op: "delete_text",
            layerName: target,
            confidence: 0.74,
            positionHint: "from_screenshot_ocr",
          }),
        );
      }
    }
  }
  // Expand short "X改成Y" edits using nearby full copy lines from screenshot OCR.
  // Example: "X60改成X50" + "X60旗舰上新" => layerName "X60旗舰上新", newText "X50旗舰上新"
  const instructionLinePattern = /(改成|改为|改到|文件名|保存|完成后|导出|打包|主图存放)/;
  const contentLines = lines.filter((line) => !instructionLinePattern.test(line));
  const replaceSourceInLine = (line, source, target) => {
    if (line.includes(source)) {
      return line.replace(source, target).trim();
    }
    if (source.length > 1) {
      const tail = source.slice(1).replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
      const relaxed = new RegExp(`[A-Za-z&€¥￥]?${tail}`);
      if (relaxed.test(line)) {
        return line.replace(relaxed, target).trim();
      }
    }
    return "";
  };
  const shouldExpandByContext = (source) => {
    const s = String(source || "").trim();
    if (!s) return false;
    // Expand mostly for short alnum-like tokens where OCR gives shorthand
    // and we need full copy for precise layer targeting (e.g. X60, 15min).
    return /^[A-Za-z0-9&€¥￥._-]+$/i.test(s);
  };
  const expanded = edits.map((edit) => {
    if (edit.op !== "replace_text") return edit;
    const source = String(edit.layerName || "").trim();
    const target = String(edit.newText || "").trim();
    if (!shouldExpandByContext(source)) return edit;
    if (!source || !target) return edit;
    const relaxedSourceTail = source.length > 1 ? source.slice(1) : source;
    const candidates = contentLines
      .filter((line) => line.includes(source) || (relaxedSourceTail && line.includes(relaxedSourceTail)))
      .filter((line) => line.length > source.length)
      .filter((line) => line.length <= 48)
      .filter((line) => !line.includes("改成") && !line.includes("改为"));
    if (candidates.length === 0) return edit;
    const best = candidates.sort((a, b) => a.length - b.length)[0];
    const replaced = replaceSourceInLine(best, source, target);
    if (!replaced || replaced === best) return edit;
    return normalizeEdit({
      op: "replace_text",
      layerName: best,
      newText: replaced,
      confidence: 0.84,
      positionHint: "from_screenshot_ocr_context",
    });
  });
  // Keep order while removing duplicates.
  const seen = new Set();
  return expanded.filter((item) => {
    const key = `${item.op}|${item.layerName}|${item.newText}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

function parseTaskFromText(text) {
  const fileHint = parseFileHint(text || "");
  const edits = parseEditsFromChinese(text || "");
  if (edits.length === 0) {
    return { ok: false, error: "未识别到修改项（支持“把X改成Y”或“删除X”）。" };
  }
  return {
    ok: true,
    task: {
      fileHint,
      modifications: edits,
    },
  };
}

export function parseIntentRequest(request = {}) {
  const text = typeof request.text === "string" ? request.text.trim() : "";
  const screenshotPath =
    typeof request.screenshotPath === "string" ? request.screenshotPath.trim() : "";
  const rawTasks = Array.isArray(request.tasks) ? request.tasks : [];
  const screenshotOcrText = extractScreenshotOcrText(screenshotPath);
  const screenshotEdits = parseEditsFromOcrText(screenshotOcrText);
  const textEdits = parseEditsFromChinese(text);
  const inferredEdits = textEdits.length > 0 ? textEdits : screenshotEdits;
  const parsedTasks = [];

  if (rawTasks.length > 0) {
    for (const item of rawTasks) {
      const modifications = Array.isArray(item?.modifications)
        ? item.modifications.map(normalizeEdit).filter((x) => x.layerName)
        : inferredEdits;
      if (modifications.length === 0) continue;
      const exactPath = item?.exactPath ? path.resolve(String(item.exactPath)) : undefined;
      const fileHint = item?.fileHint ? String(item.fileHint).trim() : undefined;
      parsedTasks.push({
        exactPath,
        fileHint,
        modifications,
      });
    }
  } else if (text) {
    const parsed = parseTaskFromText(text);
    if (parsed.ok) {
      parsedTasks.push(parsed.task);
    } else if (screenshotEdits.length > 0) {
      parsedTasks.push({
        exactPath: parseAbsolutePath(text) || undefined,
        fileHint: parseFileHint(text || ""),
        modifications: screenshotEdits,
      });
    } else {
      return { ok: false, code: "E_PARSE_FAILED", message: parsed.error };
    }
  } else {
    return { ok: false, code: "E_PARSE_FAILED", message: "请求缺少 text 或 tasks。" };
  }

  if (parsedTasks.length === 0) {
    return { ok: false, code: "E_PARSE_FAILED", message: "未生成任何有效任务。" };
  }

  const fileHintCandidates = [
    ...extractFileHintsFromText(screenshotOcrText),
    ...extractFileHintsFromText(text),
  ];
  const fallbackFileHint = fileHintCandidates[0] || "";
  if (fallbackFileHint) {
    for (const task of parsedTasks) {
      if (!task.exactPath && !task.fileHint) {
        task.fileHint = fallbackFileHint;
      }
    }
  }
  const missingFileHint = parsedTasks.some((task) => !task.exactPath && !task.fileHint);
  if (missingFileHint) {
    return {
      ok: false,
      code: "E_PARSE_FAILED",
      message:
        "未识别到 PSD/PSB 文件线索。请在文本写明文件名（如 xxx.psd），或确保截图内文件名可被 OCR 识别（tesseract 或 macOS Vision OCR）。",
    };
  }

  const taskPreviews = parsedTasks.map((task, idx) => {
    const edits = task.modifications.map((item) => ({
      layerName: item.layerName,
      op: item.op,
      newText: item.newText,
      confidence: item.confidence,
      positionHint: item.positionHint,
    }));
    const minConfidence = edits.reduce((min, item) => Math.min(min, item.confidence), 1);
    return {
      taskId: `main-image-${Date.now()}-${idx + 1}`,
      exactPath: task.exactPath,
      fileHint: task.fileHint,
      edits,
      minConfidence,
    };
  });

  return { ok: true, tasks: taskPreviews };
}

import { spawnSync } from "node:child_process";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { resolvePsdPath, DEFAULT_INDEX } from "../../psd-automator/lib/index-resolver.js";
import { expandHome } from "../../psd-automator/lib/paths.js";

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const runTaskScript = path.resolve(__dirname, "../../psd-automator/scripts/run-task.js");

function ensureDir(dirPath) {
  fs.mkdirSync(dirPath, { recursive: true });
}

function writeJsonTemp(prefix, payload) {
  const dir = path.join(os.tmpdir(), "openclaw-main-image-editor");
  ensureDir(dir);
  const filePath = path.join(dir, `${prefix}-${Date.now()}-${Math.random().toString(16).slice(2)}.json`);
  fs.writeFileSync(filePath, JSON.stringify(payload, null, 2), "utf8");
  return filePath;
}

function runPsdAutomator(taskPath, params) {
  const args = [runTaskScript, "--task", taskPath];
  if (params.indexPath) {
    args.push("--index", params.indexPath);
  }
  if (params.dryRun) {
    args.push("--dry-run");
  }
  const result = spawnSync("node", args, {
    encoding: "utf8",
    timeout: params.timeoutMs || 300_000,
  });
  if (result.error && result.error.code === "ETIMEDOUT") {
    return {
      process: result,
      payload: {
        status: "error",
        code: "E_EXEC_TIMEOUT",
        message: "psd-automator runner timed out.",
      },
    };
  }
  const text = (result.stdout || result.stderr || "").trim();
  let parsed;
  if (text) {
    try {
      parsed = JSON.parse(text);
    } catch {
      parsed = {
        status: "error",
        code: "E_EXEC_FAILED",
        message: text,
      };
    }
  } else {
    parsed = {
      status: "error",
      code: "E_EXEC_FAILED",
      message: "Runner returned empty output.",
    };
  }
  return { process: result, payload: parsed };
}

function resolveTargetPath(task, indexPath) {
  const resolved = resolvePsdPath({
    exactPath: task.exactPath,
    fileHint: task.fileHint,
    indexPath: path.resolve(expandHome(indexPath || DEFAULT_INDEX)),
  });
  return resolved;
}

function backupTarget(pathToBackup) {
  const stamp = new Date().toISOString().replace(/[-:TZ.]/g, "").slice(0, 14);
  const backupPath = `${pathToBackup}.txn-bak.${stamp}`;
  fs.copyFileSync(pathToBackup, backupPath);
  return backupPath;
}

function cleanupPaths(paths = []) {
  for (const p of paths) {
    if (!p) continue;
    try {
      if (fs.existsSync(p)) {
        const stat = fs.statSync(p);
        if (stat.isDirectory()) {
          fs.rmSync(p, { recursive: true, force: true });
        } else {
          fs.rmSync(p, { force: true });
        }
      }
    } catch {
      // best effort cleanup
    }
  }
}

function parseAvailableLayersFromMessage(message) {
  const text = String(message || "");
  const marker = "AVAILABLE_LAYERS:";
  const idx = text.indexOf(marker);
  if (idx < 0) return [];
  const tail = text.slice(idx + marker.length);
  const firstLine = (tail.split(/\r?\n/)[0] || "").split(/\.\s*(?:\r?直线:|line:)/)[0] || "";
  return firstLine
    .split(",")
    .map((item) => item.trim())
    .filter(Boolean);
}

function remapEditsByAvailableLayers(edits, availableLayers) {
  if (!Array.isArray(edits) || edits.length === 0 || availableLayers.length === 0) return null;
  const looseMatch = (a, b) => {
    const left = String(a || "").trim();
    const right = String(b || "").trim();
    if (!left || !right) return false;
    if (left === right) return true;
    if (left.includes(right) || right.includes(left)) return true;
    const leftTail = left.length > 1 ? left.slice(1) : left;
    const rightTail = right.length > 1 ? right.slice(1) : right;
    return Boolean(
      (leftTail && (right.includes(leftTail) || rightTail.includes(leftTail))) ||
        (rightTail && (left.includes(rightTail) || leftTail.includes(rightTail))),
    );
  };
  const replaceWithin = (line, source, target) => {
    const value = String(line || "");
    if (!value) return "";
    if (value.includes(source)) {
      return value.replace(source, target);
    }
    if (source.length > 1) {
      const tail = source.slice(1).replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
      const relaxed = new RegExp(`[A-Za-z&€¥￥]?${tail}`);
      if (relaxed.test(value)) {
        return value.replace(relaxed, target);
      }
    }
    return "";
  };
  const pickBestLayer = (needle) => {
    const n = String(needle || "").trim();
    if (!n) return "";
    const candidates = availableLayers
      .map((layer) => {
        const l = String(layer || "").trim();
        if (!l) return null;
        if (!looseMatch(l, n)) return null;
        // lower score is better
        let score = 1000;
        if (l === n) score = 0;
        else if (l.startsWith(n) || l.endsWith(n)) score = 8 + Math.abs(l.length - n.length);
        else if (l.includes(n) || n.includes(l)) score = 16 + Math.abs(l.length - n.length);
        else score = 40 + Math.abs(l.length - n.length);
        return { layer: l, score };
      })
      .filter(Boolean)
      .sort((a, b) => a.score - b.score);
    return candidates[0]?.layer || "";
  };
  let changed = false;
  const remapped = edits.map((edit) => {
    const name = String(edit.layerName || "").trim();
    if (!name) return edit;
    const exact = availableLayers.find((layer) => layer === name);
    if (exact) return edit;
    if (edit.op === "replace_text" && edit.newText) {
      const byTarget = pickBestLayer(edit.newText);
      if (byTarget) {
        changed = true;
        const rewritten = replaceWithin(byTarget, name, edit.newText);
        const keepStructure = byTarget.includes(edit.newText) ? byTarget : edit.newText;
        return {
          ...edit,
          layerName: byTarget,
          // Prefer structure-preserving rewrite; when source is already replaced,
          // keep the full candidate copy instead of collapsing into short target text.
          newText: rewritten || keepStructure,
        };
      }
    }
    const contains = pickBestLayer(name);
    if (!contains) return edit;
    changed = true;
    if (edit.op === "replace_text" && edit.newText) {
      const rewritten = replaceWithin(contains, name, edit.newText);
      const keepStructure = contains.includes(edit.newText) ? contains : edit.newText;
      return {
        ...edit,
        layerName: contains,
        newText: rewritten || keepStructure,
      };
    }
    return { ...edit, layerName: contains };
  });
  return changed ? remapped : null;
}

export function buildPsdTask(previewTask, opts = {}) {
  return {
    taskId: previewTask.taskId,
    input: {
      exactPath: previewTask.exactPath,
      fileHint: previewTask.fileHint,
      edits: previewTask.edits.map((item) => ({
        layerName: item.layerName,
        newText: item.newText,
        op: item.op,
      })),
    },
    workflow: {
      sourceMode: "inplace",
    },
    output: {
      psd: { mode: "overwrite" },
      exports: Array.isArray(opts.exports) ? opts.exports : [],
      bundle: opts.bundle || {},
    },
    options: {
      styleLock: true,
      createBackup: false,
      retryOnLockedFile: true,
      maxRetries: 2,
      bundleZip: opts.bundleZip === true,
      ...(opts.matchImagePath ? { matchImagePath: opts.matchImagePath } : {}),
    },
  };
}

export function shouldRequireConfirmation(previewTasks, threshold, force = false, dryRun = false) {
  if (dryRun || force) return false;
  return previewTasks.some((task) => Number(task.minConfidence) < Number(threshold));
}

export function executeTransactionalBatch(params) {
  const threshold = Number.isFinite(Number(params.threshold)) ? Number(params.threshold) : 0.8;
  const previewTasks = params.previewTasks || [];
  if (previewTasks.length === 0) {
    return {
      ok: false,
      result: {
        status: "error",
        code: "E_TASK_INVALID",
        message: "No preview tasks to execute.",
      },
    };
  }

  if (shouldRequireConfirmation(previewTasks, threshold, params.force, params.dryRun)) {
    return {
      ok: true,
      result: {
        status: "needs_confirmation",
        code: "E_LOW_CONFIDENCE",
        summary: `Low confidence tasks detected (threshold=${threshold}).`,
        threshold,
        dryRun: false,
        forced: false,
        previewTasks,
      },
    };
  }

  const indexPath = params.indexPath || DEFAULT_INDEX;
  const rollbackRecords = [];
  const producedPaths = new Set();
  const executed = [];

  try {
    for (const task of previewTasks) {
      const resolved = resolveTargetPath(task, indexPath);
      if (!resolved.ok) {
        throw {
          code: resolved.code || "E_FILE_NOT_FOUND",
          message: resolved.message || "Target PSD resolve failed.",
          taskId: task.taskId,
        };
      }
      const backupPath = backupTarget(resolved.path);
      rollbackRecords.push({ originalPath: resolved.path, backupPath });

      const psdTask = buildPsdTask(task, {
        exports: params.exports,
        bundle: params.bundle,
        bundleZip: params.bundleZip,
        matchImagePath: params.screenshotPath,
      });
      const tempTaskPath = writeJsonTemp("main-image-task", psdTask);
      let run = runPsdAutomator(tempTaskPath, {
        indexPath,
        dryRun: Boolean(params.dryRun),
      });
      cleanupPaths([tempTaskPath]);

      let payload = run.payload || {};
      if (payload.code === "E_LAYER_NOT_FOUND" && typeof payload.message === "string") {
        const availableLayers = parseAvailableLayersFromMessage(payload.message);
        const remappedEdits = remapEditsByAvailableLayers(task.edits, availableLayers);
        if (remappedEdits && remappedEdits.length > 0) {
          const retryTask = buildPsdTask(
            {
              ...task,
              edits: remappedEdits,
            },
            {
              exports: params.exports,
              bundle: params.bundle,
              bundleZip: params.bundleZip,
              matchImagePath: params.screenshotPath,
            },
          );
          const retryTaskPath = writeJsonTemp("main-image-task-retry", retryTask);
          run = runPsdAutomator(retryTaskPath, {
            indexPath,
            dryRun: Boolean(params.dryRun),
          });
          cleanupPaths([retryTaskPath]);
          payload = run.payload || payload;
        }
      }
      const status = payload.status === "success" || payload.status === "dry-run" ? "success" : "error";
      executed.push({
        taskId: task.taskId,
        status,
        resolvedPath: payload.resolvedPath,
        psdOutputPath: payload.psdOutputPath,
        pngOutputPaths: payload.pngOutputPaths || [],
        selectedPngPath: payload.selectedPngPath,
        bundleZipPath: payload.bundleZipPath,
        code: payload.code,
        message: payload.message,
      });

      for (const p of payload.pngOutputPaths || []) producedPaths.add(p);
      if (payload.bundleZipPath) producedPaths.add(payload.bundleZipPath);

      if (status !== "success") {
        throw {
          code: payload.code || "E_EXEC_FAILED",
          message: payload.message || "psd-automator execution failed.",
          taskId: task.taskId,
        };
      }
    }

    return {
      ok: true,
      result: {
        status: params.dryRun ? "dry-run" : "success",
        code: "OK",
        summary: params.dryRun
          ? "Dry-run completed. No file changes committed."
          : "Batch execution completed with rollback guard.",
        threshold,
        dryRun: Boolean(params.dryRun),
        forced: Boolean(params.force),
        previewTasks,
        executed,
        rolledBack: false,
        rollbackCount: 0,
      },
    };
  } catch (error) {
    let rollbackCount = 0;
    for (const record of rollbackRecords) {
      try {
        fs.copyFileSync(record.backupPath, record.originalPath);
        rollbackCount += 1;
      } catch {
        // keep best-effort rollback
      }
    }
    cleanupPaths([...producedPaths]);
    return {
      ok: false,
      result: {
        status: "error",
        code: error?.code || "E_EXEC_FAILED",
        summary: error?.message || "Transactional batch failed.",
        threshold,
        dryRun: Boolean(params.dryRun),
        forced: Boolean(params.force),
        previewTasks,
        executed,
        rolledBack: rollbackCount > 0,
        rollbackCount,
      },
    };
  } finally {
    // Keep backups for debugging only when keepBackups=true.
    if (!params.keepBackups) {
      cleanupPaths(rollbackRecords.map((x) => x.backupPath));
    }
  }
}

#!/usr/bin/env node
import fs from "node:fs";
import path from "node:path";
import { parseIntentRequest } from "../lib/intent-parser.js";
import { executeTransactionalBatch } from "../lib/task-orchestrator.js";

function parseArgs(argv) {
  const args = {
    request: "",
    dryRun: false,
    force: false,
    index: "",
    threshold: undefined,
    help: false,
  };
  for (let i = 2; i < argv.length; i += 1) {
    const arg = argv[i];
    if (arg === "--request") {
      args.request = argv[i + 1] || "";
      i += 1;
    } else if (arg === "--dry-run") {
      args.dryRun = true;
    } else if (arg === "--force") {
      args.force = true;
    } else if (arg === "--index") {
      args.index = argv[i + 1] || "";
      i += 1;
    } else if (arg === "--threshold") {
      args.threshold = Number(argv[i + 1]);
      i += 1;
    } else if (arg === "--help" || arg === "-h") {
      args.help = true;
    }
  }
  return args;
}

function readRequest(filePath) {
  const resolved = path.resolve(filePath);
  const raw = fs.readFileSync(resolved, "utf8");
  return JSON.parse(raw);
}

function printResultAndExit(payload, code) {
  process.stdout.write(`${JSON.stringify(payload, null, 2)}\n`);
  process.exit(code);
}

function normalizeRequest(base, args) {
  const request = { ...(base || {}) };
  const exec = request.execution || {};
  request.execution = {
    ...exec,
    dryRun: Boolean(args.dryRun || exec.dryRun),
    force: Boolean(args.force || exec.force),
    indexPath: args.index || exec.indexPath,
    rollbackPolicy: "rollback_all",
  };
  if (Number.isFinite(args.threshold)) {
    request.confidenceThreshold = Number(args.threshold);
  }
  return request;
}

function resolveExports(request) {
  const requestText = String(request?.text || "");
  const skipExport = /(不导出|仅修改|只改文案|不需要导图)/.test(requestText);
  const toDesktop = /(桌面)/.test(String(request?.text || ""));
  if (skipExport) return [];
  return [
    {
      format: "png",
      mode: "layer_sets",
      dir: toDesktop ? "~/Desktop" : undefined,
      folderName: `main-image-${Date.now()}`,
    },
  ];
}

function main() {
  const args = parseArgs(process.argv);
  if (args.help || !args.request) {
    process.stdout.write(
      "Usage: run-main-image-editor.js --request <request.json> [--dry-run] [--force] [--index <index>] [--threshold <0-1>]\n",
    );
    process.exit(args.help ? 0 : 1);
  }

  let request;
  try {
    request = normalizeRequest(readRequest(args.request), args);
  } catch (error) {
    printResultAndExit(
      {
        status: "error",
        code: "E_TASK_INVALID",
        message: `Cannot read request: ${error.message}`,
      },
      1,
    );
  }

  const parsed = parseIntentRequest(request);
  if (!parsed.ok) {
    printResultAndExit(
      {
        requestId: request.requestId || `main-image-request-${Date.now()}`,
        status: "error",
        code: parsed.code,
        message: parsed.message,
      },
      1,
    );
  }

  const threshold = Number.isFinite(Number(request.confidenceThreshold))
    ? Number(request.confidenceThreshold)
    : 0.8;
  const execution = request.execution || {};
  const exports = resolveExports(request);
  const result = executeTransactionalBatch({
    previewTasks: parsed.tasks,
    threshold,
    force: Boolean(execution.force),
    dryRun: Boolean(execution.dryRun),
    indexPath: execution.indexPath,
    screenshotPath: request.screenshotPath,
    bundleZip: execution.bundleZip !== false,
    bundle: {
      zipName: `main-image-${Date.now()}.zip`,
    },
    exports,
    keepBackups: false,
  });

  const payload = {
    requestId: request.requestId || `main-image-request-${Date.now()}`,
    ...result.result,
  };
  printResultAndExit(payload, payload.status === "error" ? 1 : 0);
}

main();
